function svg(name, attributes = {}) {
  const node = document.createElementNS(SVG_NS, name);
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  return node;
}

function parseRoute(value) {
  return value.toUpperCase().split(/[\s,\-]+/).map(item => item.trim()).filter(Boolean);
}

function formatUpdate(generatedAt, commitId) {
  const timestamp = new Date(generatedAt).toISOString().replace("T", " ").replace(/\.\d{3}Z$/, " UTC");
  return `updated ${timestamp}${commitId ? ` • commit ${commitId.slice(-6)}` : ""}`;
}

function airportMatchRank(airport, value) {
  const query = value.trim().toUpperCase();
  if (!query) return 1;
  const prefixed = query.startsWith("K") ? query : `K${query}`;
  if (airport.id === prefixed) return 0;
  if (airport.id.startsWith(prefixed)) return 1;
  if (airport.id.includes(query)) return 2;
  return `${airport.name} ${airport.city} ${airport.state}`.toUpperCase().includes(query) ? 3 : Infinity;
}

function renderAirportOptions(value) {
  const matches = [...state.airports.values()]
    .map(airport => ({ airport, rank: airportMatchRank(airport, value) }))
    .filter(match => Number.isFinite(match.rank))
    .sort((a, b) => a.rank - b.rank || a.airport.id.localeCompare(b.airport.id));
  airportOptions.replaceChildren(...matches.map(({ airport }) => {
    const option = document.createElement("option");
    option.value = airport.id;
    option.label = `${airport.name} — ${airport.city}, ${airport.state}`;
    return option;
  }));
}

async function sha256Hex(bytes) {
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)].map(value => value.toString(16).padStart(2, "0")).join("");
}

async function verifyPackage(latest, payload) {
  if (payload.byteLength !== latest.artifact.bytes) throw new Error("Fuel data byte count failed");
  if (await sha256Hex(payload) !== latest.artifact.sha256) throw new Error("Fuel data checksum failed");
  const packageData = JSON.parse(new TextDecoder().decode(payload));
  if (packageData.schema !== "fuel-airports/v2") throw new Error("Unsupported fuel data schema");
  if (packageData.data_version !== latest.data_version) throw new Error("Fuel data version mismatch");
  packageData.commit_id = /^[0-9a-f]{40}$/.test(latest.commit_id || "") ? latest.commit_id : null;
  return packageData;
}

async function fetchNetworkData() {
  let commitId = null;
  if (!isStratux()) {
    try {
      const response = await fetch(DATA_COMMIT_URL, { cache: "no-store" });
      if (!response.ok) throw new Error(`GitHub commits returned ${response.status}`);
      commitId = (await response.json())[0]?.sha;
      if (!/^[0-9a-f]{40}$/.test(commitId || "")) throw new Error("GitHub returned an invalid commit ID");
    } catch (error) {
      console.warn("Fuel data commit unavailable", error);
      commitId = null;
    }
  }
  const sourceBaseUrl = commitId
    ? new URL(`https://raw.githubusercontent.com/freefly42/fuel-map/${commitId}/data/`)
    : DATA_BASE_URL;
  const latestUrl = new URL("latest.json", sourceBaseUrl);
  latestUrl.searchParams.set("v", Date.now());
  const latestResponse = await fetch(latestUrl, { cache: "no-store" });
  if (!latestResponse.ok) throw new Error(`latest.json returned ${latestResponse.status}`);
  const latest = await latestResponse.json();
  if (latest.schema !== "fuel-airports-latest/v1") throw new Error("Unsupported data manifest");
  latest.commit_id = commitId;
  const artifactUrl = new URL(`${latest.artifact.path}?v=${encodeURIComponent(latest.data_version)}`, sourceBaseUrl).href;
  const artifactResponse = await fetch(artifactUrl, { cache: "no-store" });
  if (!artifactResponse.ok) throw new Error(`${latest.artifact.path} returned ${artifactResponse.status}`);
  const payload = await artifactResponse.arrayBuffer();
  const packageData = await verifyPackage(latest, payload);
  const cache = await caches.open(VERIFIED_CACHE);
  const cachedArtifactUrl = new URL(`${latest.artifact.path}?v=${encodeURIComponent(latest.data_version)}`, DATA_BASE_URL).href;
  await cache.put(cachedArtifactUrl, new Response(payload, { headers: { "Content-Type": "application/json" } }));
  await cache.put(VERIFIED_MANIFEST_URL, new Response(JSON.stringify(latest), { headers: { "Content-Type": "application/json" } }));
  return packageData;
}

async function fetchCachedData() {
  const cache = await caches.open(VERIFIED_CACHE);
  const latestResponse = await cache.match(VERIFIED_MANIFEST_URL);
  if (!latestResponse) throw new Error("No verified offline fuel data");
  const latest = await latestResponse.json();
  const artifactUrl = new URL(`${latest.artifact.path}?v=${encodeURIComponent(latest.data_version)}`, DATA_BASE_URL).href;
  const artifactResponse = await cache.match(artifactUrl);
  if (!artifactResponse) throw new Error("Verified offline artifact is missing");
  return verifyPackage(latest, await artifactResponse.arrayBuffer());
}

function usePackageData(packageData) {
  state.airports = new Map(packageData.airports.map(airport => [airport.id, airport]));
  renderAirportOptions(planningLocationInput.value);
  state.stateAveragePrices = packageData.state_average_100ll_price_usd_per_gallon || {};
  document.querySelector("#data-status").textContent =
    `${packageData.coverage.airport_count} public airports • ${packageData.coverage.fuel_airport_count} advertise 100LL • all 50 states • ${formatUpdate(packageData.generated_at, packageData.commit_id)} • works offline after first load`;
}

async function loadData() {
  let packageData;
  try {
    packageData = await fetchNetworkData();
  } catch (networkError) {
    console.warn("Fuel data load failed; trying verified cache", networkError);
    packageData = await fetchCachedData();
  }
  usePackageData(packageData);
  return packageData;
}

function isStratux() {
  return location.hostname === "192.168.10.1" || /(^|\.)stratux(?:\.local)?$/i.test(location.hostname);
}

function mapPosition(airport) {
  const { latitude, longitude } = airport.position;
  if (latitude > 50) {
    const alaskaLongitude = longitude > 0 ? longitude - 360 : longitude;
    return { longitude: -125 + (alaskaLongitude + 190) / 5, latitude: 24 + (latitude - 51) * 8 / 21 };
  }
  if (latitude < 23.5 && longitude < -150) {
    return { longitude: -111 + (longitude + 161), latitude: 25 + (latitude - 18) * 4 / 5 };
  }
  return airport.position;
}

function projection(airports) {
  const points = airports.map(mapPosition).concat(Object.values(STATE_OUTLINES).flat(2).map(([longitude, latitude]) => ({ longitude, latitude })));
  const west = Math.min(...points.map(point => point.longitude));
  const east = Math.max(...points.map(point => point.longitude));
  const south = Math.min(...points.map(point => point.latitude));
  const north = Math.max(...points.map(point => point.latitude));
  return airport => {
    const position = mapPosition(airport);
    return {
      x: 35 + ((position.longitude - west) / (east - west)) * 930,
      y: 525 - ((position.latitude - south) / (north - south)) * 490,
    };
  };
}

function addStateOutlines(project) {
  for (const rings of [...Object.values(STATE_OUTLINES), ...Object.values(INSET_STATE_OUTLINES)]) {
    for (const ring of rings) {
      const points = ring.map(([longitude, latitude]) => project({ position: { longitude, latitude } })).map(point => `${point.x},${point.y}`).join(" ");
      map.append(svg("polyline", { points, class: "state-outline" }));
    }
  }
  for (const ring of GREAT_LAKE_OUTLINES) {
    const points = ring.map(([longitude, latitude]) => project({ position: { longitude, latitude } })).map(point => `${point.x},${point.y}`).join(" ");
    map.append(svg("polygon", { points, class: "lake-outline" }));
  }
}

function showAirport(airport, event) {
  const heading = document.createElement("h2");
  heading.textContent = `${airport.id} — ${airport.name}`;
  const description = document.createElement("p");
  const deal = airport.deal_rating === 2 ? " • Super Deal" : airport.deal_rating === 1 ? " • Great Deal" : "";
  description.textContent = `${airport.city}, ${airport.state}${deal}${airport.fuel_24_hours === true ? " • 24-hour fuel" : ""}${airport.services.fuel_100ll ? "" : " • 100LL not listed"}`;
  const close = document.createElement("button");
  close.className = "tooltip-close";
  close.type = "button";
  close.setAttribute("aria-label", "Close airport details");
  close.textContent = "×";
  close.addEventListener("click", hideAirport);
  const offers = document.createElement("ul");
  offers.className = "price-list";
  for (const offer of airport.offers) {
    const item = document.createElement("li");
    const provider = document.createElement("strong");
    const prices = document.createElement("span");
    const guaranteed = offer.source_updated === "Guaranteed";
    const suffix = guaranteed ? "*" : "";
    const age = guaranteed ? "guaranteed" : Number.isInteger(offer.price_age_days)
      ? `${offer.price_age_days} day${offer.price_age_days === 1 ? "" : "s"} old`
      : "age unknown";
    provider.textContent = offer.provider;
    prices.textContent = typeof offer.price_usd_per_gallon === "number"
      ? `100LL ${formatPrice(offer.price_usd_per_gallon)}${suffix} • ${age}`
      : `Self ${servicePrice(airport.services.self_service_100ll, offer.self_service_price_usd_per_gallon, suffix)} • Full ${servicePrice(airport.services.full_service_100ll, offer.full_service_price_usd_per_gallon, suffix)} • ${age}`;
    item.append(provider, prices);
    offers.append(item);
  }
  const warning = document.createElement("p");
  warning.className = "warning";
  warning.textContent = airport.fuel_unavailable ? "Fuel NOTAM — verify current availability" : "";
  const navigation = document.createElement("p");
  navigation.className = "navigation";
  navigation.textContent = navigationText(airport);
  tooltip.replaceChildren(close, heading, description);
  if (navigation.textContent) tooltip.append(navigation);
  if (airport.fuel_unavailable) tooltip.append(warning);
  tooltip.append(offers);
  tooltip.hidden = false;
  const card = map.closest(".map-card").getBoundingClientRect();
  const bounds = tooltip.getBoundingClientRect();
  tooltip.style.left = `${Math.max(8, Math.min(card.width - bounds.width - 8, event.clientX - card.left + 12))}px`;
  tooltip.style.top = `${Math.max(8, Math.min(card.height - bounds.height - 8, event.clientY - card.top + 12))}px`;
}

function formatPrice(price) {
  return typeof price === "number" ? `$${price.toFixed(2)}` : "--";
}

function servicePrice(service, price, suffix = "") {
  if (service === false) return "none";
  return service === true && typeof price === "number" ? `${formatPrice(price)}${suffix}` : "unknown";
}

function distanceNm(from, to) {
  const radians = value => value * Math.PI / 180;
  const latitudeDelta = radians(to.latitude - from.latitude);
  const longitudeDelta = radians(to.longitude - from.longitude);
  const a = Math.sin(latitudeDelta / 2) ** 2
    + Math.cos(radians(from.latitude)) * Math.cos(radians(to.latitude)) * Math.sin(longitudeDelta / 2) ** 2;
  const clamped = Math.min(1, a);
  return 3440.065 * 2 * Math.atan2(Math.sqrt(clamped), Math.sqrt(1 - clamped));
}

function navigationSpeed() {
  return state.locationOverride ? state.manualSpeedKnots : state.detectedSpeedKnots || state.manualSpeedKnots;
}

function parseDuration(value) {
  const match = /^(\d+):([0-5]\d)$/.exec(value.trim());
  const minutes = match ? Number(match[1]) * 60 + Number(match[2]) : NaN;
  return Number.isSafeInteger(minutes) ? minutes : null;
}

function insertDurationColon(value, inputType) {
  return /^\d{2}$/.test(value) && inputType !== "deleteContentBackward" ? `${value}:` : value;
}

function reserveMinutes(airport) {
  const speed = navigationSpeed();
  return state.fuelMinutes === null || !state.aircraftPosition || !speed
    ? null
    : state.fuelMinutes - distanceNm(state.aircraftPosition, airport.position) / speed * 60;
}

function reserveMarkerColor(reserve, normalColor) {
  return reserve !== null && reserve < 30 ? "#ff8c00"
    : reserve !== null && reserve <= 45 ? "#ffd500"
    : normalColor;
}

function airportInRange(airport) {
  const reserve = reserveMinutes(airport);
  return reserve === null || reserve >= 0;
}

function resolveRoute(route, airports = state.airports) {
  return route.map(id => airports.get(id)).filter(Boolean);
}

function navigationText(airport) {
  if (!state.aircraftPosition) return "";
  const distance = distanceNm(state.aircraftPosition, airport.position);
  const speed = navigationSpeed();
  const text = `${distance.toFixed(distance < 100 ? 1 : 0)} NM`;
  if (!speed) return text;
  const minutes = Math.max(1, Math.round(distance / speed * 60));
  const duration = minutes < 60 ? `${minutes} min` : `${Math.floor(minutes / 60)}h${minutes % 60 ? ` ${minutes % 60}m` : ""}`;
  return `${text} • ${duration} at ${Math.round(speed)} kt`;
}

function hideAirport() {
  tooltip.hidden = true;
}

function mixWithGray(color, amount) {
  return `rgb(${color.map(value => Math.round(value + (128 - value) * amount)).join(", ")})`;
}

function lowestPrice(airport, maxAge) {
  const prices = airport.offers.flatMap(offer =>
    [offer.price_usd_per_gallon, offer.self_service_price_usd_per_gallon, offer.full_service_price_usd_per_gallon]
      .filter(price => typeof price === "number" && price > 0)
      .map(price => ({ price, age: offer.price_age_days }))
  ).filter(price => maxAge === undefined || Number.isInteger(price.age) && price.age >= 0 && price.age < maxAge);
  return prices.length ? prices.reduce((best, price) => price.price < best.price ? price : best) : null;
}

function fuelColor(airport, stateAverages = state.stateAveragePrices) {
  if (airport.fuel_unavailable) return "#e31b23";
  if (airport.deal_rating === 2) return "#39ff14";
  if (airport.deal_rating === 1) return "#22c55e";
  const lowest = lowestPrice(airport);
  const average = stateAverages[airport.state_code];
  if (!lowest || typeof average !== "number") return "#808080";
  if (!Number.isInteger(lowest.age) || lowest.age < 0) return "#808080";
  const centsFromAverage = Math.round((lowest.price - average) * 100);
  const color = centsFromAverage <= -75 ? [125, 211, 252]
    : centsFromAverage < 0 ? [139, 92, 246]
    : centsFromAverage >= 75 ? [255, 140, 0]
    : [255, 213, 0];
  const fade = Math.min(1, Math.max(0, (lowest.age - 14) / 106));
  return mixWithGray(color, fade);
}

function fuelAvailable24Hours(airport) {
  // ponytail: legacy snapshots lack fuel_24_hours; remove this fallback after they are rebuilt.
  return airport.fuel_24_hours === true
    || (airport.fuel_24_hours == null && airport.services.self_service_100ll === true);
}

function makeClickable(node, airport) {
  node.addEventListener("click", event => { event.stopPropagation(); showAirport(airport, event); });
}

function airportLabel(airport, point, xOffset, yOffset, fontSize, className, fill) {
  const x = point.x + xOffset;
  const label = svg("text", { x, y: point.y - yOffset, "font-size": fontSize, class: className, fill });
  const identifier = svg("tspan", { x });
  identifier.textContent = airport.id;
  label.append(identifier);
  const recent = lowestPrice(airport, 30);
  if (recent) {
    const price = svg("tspan", { x, dy: fontSize, class: "airport-price" });
    price.textContent = formatPrice(recent.price);
    label.append(price);
  }
  makeClickable(label, airport);
  return label;
}

function addGrid() {
  for (let x = 100; x < 1000; x += 100) map.append(svg("line", { x1: x, y1: 0, x2: x, y2: 560, class: "map-grid" }));
  for (let y = 80; y < 560; y += 80) map.append(svg("line", { x1: 0, y1: y, x2: 1000, y2: y, class: "map-grid" }));
}

function renderMap() {
  const airports = [...state.airports.values()];
  const all = airports.filter(airport => airport.services.fuel_100ll).filter(airportInRange);
  const project = projection(airports);
  map.replaceChildren();
  map.setAttribute("viewBox", `${state.view.x} ${state.view.y} ${state.view.width} ${state.view.height}`);
  addGrid();
  addStateOutlines(project);

  const routeAirports = resolveRoute(state.route);
  if (routeAirports.length > 1) {
    map.append(svg("polyline", {
      points: routeAirports.map(airport => { const point = project(airport); return `${point.x},${point.y}`; }).join(" "),
      class: "route-line",
    }));
  }
  const labelAll = BASE_VIEW.width / state.view.width >= 2.2;
  const pixelUnit = state.view.width / Math.max(map.clientWidth, 1);
  const unitPerPixel = pixelUnit * state.symbolScale;
  const labels = [];
  const markers = [];
  for (const airport of all) {
    const point = project(airport);
    const radius = 5 * unitPerPixel;
    const markerColor = reserveMarkerColor(reserveMinutes(airport), fuelColor(airport));
    const marker = fuelAvailable24Hours(airport)
      ? svg("circle", { cx: point.x, cy: point.y, r: radius, fill: markerColor, class: "fuel-marker" })
      : svg("path", { d: `M ${point.x - radius} ${point.y} A ${radius} ${radius} 0 0 1 ${point.x + radius} ${point.y} Z`, fill: markerColor, class: "fuel-marker" });
    const hit = svg("circle", { cx: point.x, cy: point.y, r: Math.max(radius, 14 * pixelUnit), class: "marker-hit" });
    makeClickable(hit, airport);
    markers.push(marker, hit);
    labels.push(airportLabel(airport, point, 6 * unitPerPixel, 5 * unitPerPixel, 9 * unitPerPixel, `airport-label${labelAll ? " visible" : ""}`, fuelColor(airport)));
  }
  map.append(...labels, ...markers);

  const routeLabels = [];
  const routeMarkers = [];
  for (const airport of routeAirports) {
    const point = project(airport);
    const marker = svg("circle", { cx: point.x, cy: point.y, r: 7 * unitPerPixel, class: `route-marker${airport.fuel_unavailable ? " unavailable" : ""}` });
    makeClickable(marker, airport);
    routeMarkers.push(marker);
    routeLabels.push(airportLabel(airport, point, 8 * unitPerPixel, 7 * unitPerPixel, 10 * unitPerPixel, "airport-label route-label", airport.fuel_unavailable ? "#ed6a5a" : "#f0f"));
  }
  map.append(...routeLabels, ...routeMarkers);
  if (state.aircraftPosition) {
    const point = project({ position: state.aircraftPosition });
    const size = 42 * pixelUnit * state.symbolScale;
    map.append(svg("image", { href: "./RedPlane.svg", x: point.x - size / 2, y: point.y - size / 2, width: size, height: size, class: "ownship-marker", role: "img", "aria-label": "Aircraft position" }));
  }
}

function applyRoute() {
  hideAirport();
  state.route = parseRoute(routeInput.value);
  const missing = state.route.filter(id => !state.airports.has(id));
  const routeAirports = resolveRoute(state.route);
  state.view = routeAirports.length
    ? fitViewToPoints(routeAirports.map(projection([...state.airports.values()])))
    : { ...BASE_VIEW };
  routeMessage.textContent = !state.route.length
    ? ""
    : missing.length
    ? `Not present in the public-airport list: ${missing.join(", ")}`
    : `${state.route.length} route airport${state.route.length === 1 ? "" : "s"} shown.`;
  routeSummary.textContent = state.route.length ? state.route.join(" → ") : "Click to enter a route";
  renderMap();
}

function fitViewToPoints(points) {
  const west = Math.min(...points.map(point => point.x));
  const east = Math.max(...points.map(point => point.x));
  const north = Math.min(...points.map(point => point.y));
  const south = Math.max(...points.map(point => point.y));
  const width = Math.min(BASE_VIEW.width, Math.max(260, east - west + 160, (south - north + 90) * BASE_VIEW.width / BASE_VIEW.height));
  const height = width * BASE_VIEW.height / BASE_VIEW.width;
  return {
    x: Math.max(0, Math.min(BASE_VIEW.width - width, (west + east - width) / 2)),
    y: Math.max(0, Math.min(BASE_VIEW.height - height, (north + south - height) / 2)),
    width,
    height,
  };
}

function centerMapOnPosition(position) {
  state.view = fitViewToPoints([projection([...state.airports.values()])({ position })]);
  renderMap();
}

function zoomViewAt(view, anchor, factor) {
  const width = Math.min(BASE_VIEW.width, Math.max(60, view.width * factor));
  const height = width * (BASE_VIEW.height / BASE_VIEW.width);
  const x = anchor.x - ((anchor.x - view.x) / view.width) * width;
  const y = anchor.y - ((anchor.y - view.y) / view.height) * height;
  return {
    x: Math.max(0, Math.min(BASE_VIEW.width - width, x)),
    y: Math.max(0, Math.min(BASE_VIEW.height - height, y)),
    width,
    height,
  };
}

function zoomAt(clientX, clientY, factor) {
  hideAirport();
  const rect = map.getBoundingClientRect();
  const anchor = {
    x: state.view.x + ((clientX - rect.left) / rect.width) * state.view.width,
    y: state.view.y + ((clientY - rect.top) / rect.height) * state.view.height,
  };
  state.view = zoomViewAt(state.view, anchor, factor);
  renderMap();
}

function wheelZoomFactor(deltaY, deltaMode) {
  const scale = deltaMode === 1 ? 16 : deltaMode === 2 ? 100 : 1;
  return Math.exp(Math.max(-100, Math.min(100, deltaY * scale)) / 1000);
}

console.assert(zoomViewAt(BASE_VIEW, { x: 500, y: 280 }, 0.5).width === 500, "map zoom math failed");
console.assert(formatUpdate("2026-08-11T05:14:43Z", `${"a".repeat(34)}123456`) === "updated 2026-08-11 05:14:43 UTC • commit 123456", "update label formatting failed");
console.assert(fitViewToPoints([{ x: 400, y: 230 }, { x: 600, y: 330 }]).width < BASE_VIEW.width, "route fit math failed");
console.assert(resolveRoute(["A", "B"], new Map([["A", {}], ["B", {}]])).length === 2, "complete route resolution failed");
console.assert(airportMatchRank({ id: "KDAL", name: "Love Field", city: "Dallas", state: "TX" }, "DAL") === 0
  && airportMatchRank({ id: "DAL", name: "Other", city: "Other", state: "TX" }, "DAL") === 2
  && airportMatchRank({ id: "KADS", name: "Addison", city: "Dallas", state: "TX" }, "DAL") === 3, "airport match ordering failed");
const colorCheck = { state_code: "TX", fuel_unavailable: false, deal_rating: 0, offers: [{ price_age_days: 14, self_service_price_usd_per_gallon: 5.94, full_service_price_usd_per_gallon: null }] };
const texasAverage = { TX: 6.69 };
console.assert(fuelColor(colorCheck, texasAverage) === "rgb(125, 211, 252)", "sky-blue fuel price color failed");
colorCheck.offers[0].self_service_price_usd_per_gallon = 5.95;
console.assert(fuelColor(colorCheck, texasAverage) === "rgb(139, 92, 246)", "indigo fuel price color failed");
colorCheck.offers[0].self_service_price_usd_per_gallon = 6.69;
console.assert(fuelColor(colorCheck, texasAverage) === "rgb(255, 213, 0)", "yellow fuel price color failed");
colorCheck.offers[0].self_service_price_usd_per_gallon = 7.44;
console.assert(fuelColor(colorCheck, texasAverage) === "rgb(255, 140, 0)", "orange fuel price color failed");
colorCheck.deal_rating = 2;
console.assert(fuelColor(colorCheck, texasAverage) === "#39ff14", "Super Deal color failed");
colorCheck.deal_rating = 0;
colorCheck.offers[0].price_age_days = 120;
console.assert(fuelColor(colorCheck, texasAverage) === "rgb(128, 128, 128)", "fuel age fade failed");
console.assert(lowestPrice(colorCheck, 30) === null && wheelZoomFactor(1, 0) < 1.01, "fresh price or smooth zoom failed");
console.assert(servicePrice(false, 5.99) === "none" && servicePrice(true, null) === "unknown" && servicePrice(true, 5.99) === "$5.99", "service price labels failed");
console.assert(servicePrice(true, 5.99, "*") === "$5.99*", "guaranteed price label failed");
console.assert(insertDurationColon("03", "insertText") === "03:" && insertDurationColon("03", "deleteContentBackward") === "03", "duration colon insertion failed");
console.assert(Math.abs(distanceNm({ latitude: 32.8968, longitude: -97.038 }, { latitude: 32.8998, longitude: -97.0403 }) - 0.2) < 0.1, "nautical-mile distance failed");
state.aircraftPosition = { latitude: 0, longitude: 0 };
state.manualSpeedKnots = 120;
state.fuelMinutes = 90;
const navigationCheck = { position: { latitude: 0, longitude: 1.99 } };
console.assert(navigationText(navigationCheck).includes("1h at 120 kt")
  && parseDuration("30:15") === 1815 && parseDuration("3:75") === null
  && reserveMarkerColor(reserveMinutes(navigationCheck), "normal") === "#ffd500"
  && reserveMarkerColor(29, "normal") === "#ff8c00"
  && reserveMarkerColor(46, "normal") === "normal", "fuel range planning failed");
state.aircraftPosition = null;
state.manualSpeedKnots = null;
state.fuelMinutes = null;
console.assert(fuelAvailable24Hours({ fuel_24_hours: true, services: {} })
  && !fuelAvailable24Hours({ fuel_24_hours: false, services: { self_service_100ll: true } }), "24-hour marker shape failed");
console.assert(Object.keys(STATE_OUTLINES).length === 48
  && Object.values(STATE_OUTLINES).flat().every(ring => ring.length > 2 && ring[0].join() === ring.at(-1).join()), "lower-48 state outlines failed");
console.assert(Object.keys(INSET_STATE_OUTLINES).join() === "AK,HI"
  && Object.values(INSET_STATE_OUTLINES).flat().every(ring => ring.length > 3 && ring[0].join() === ring.at(-1).join()), "state inset outlines failed");
console.assert(GREAT_LAKE_OUTLINES.length === 5
  && GREAT_LAKE_OUTLINES.every(ring => ring.length > 3 && ring[0].join() === ring.at(-1).join()), "Great Lakes outlines failed");
map.addEventListener("wheel", event => {
  event.preventDefault();
  zoomAt(event.clientX, event.clientY, wheelZoomFactor(event.deltaY, event.deltaMode));
}, { passive: false });

const pointers = new Map();
let pinchDistance = null;

map.addEventListener("pointerdown", event => {
  if (event.pointerType === "mouse" && event.button !== 0) return;
  pointers.set(event.pointerId, event);
  hideAirport();
  map.classList.add("dragging");
  if (pointers.size === 2) pinchDistance = distanceBetweenPointers();
});

map.addEventListener("pointermove", event => {
  if (!pointers.has(event.pointerId)) return;
  map.setPointerCapture(event.pointerId);
  const previous = pointers.get(event.pointerId);
  pointers.set(event.pointerId, event);
  if (pointers.size === 1) {
    event.preventDefault();
    panBy(event.clientX - previous.clientX, event.clientY - previous.clientY);
    return;
  }
  if (pointers.size !== 2) return;
  event.preventDefault();
  const currentDistance = distanceBetweenPointers();
  if (!pinchDistance || !currentDistance) return;
  const [first, second] = pointers.values();
  const previousCenter = pointersCenter(first === event ? previous : first, second === event ? previous : second);
  const currentCenter = pointersCenter(first, second);
  panBy(currentCenter.x - previousCenter.x, currentCenter.y - previousCenter.y, false);
  zoomAt(currentCenter.x, currentCenter.y, pinchDistance / currentDistance);
  pinchDistance = currentDistance;
});

function panBy(clientDeltaX, clientDeltaY, render = true) {
  const rect = map.getBoundingClientRect();
  state.view.x = Math.max(0, Math.min(BASE_VIEW.width - state.view.width, state.view.x - clientDeltaX * state.view.width / rect.width));
  state.view.y = Math.max(0, Math.min(BASE_VIEW.height - state.view.height, state.view.y - clientDeltaY * state.view.height / rect.height));
  if (render) renderMap();
}

function distanceBetweenPointers() {
  const [first, second] = pointers.values();
  return Math.hypot(first.clientX - second.clientX, first.clientY - second.clientY);
}

function pointersCenter(first, second) {
  return { x: (first.clientX + second.clientX) / 2, y: (first.clientY + second.clientY) / 2 };
}

function releasePointer(event) {
  pointers.delete(event.pointerId);
  pinchDistance = pointers.size === 2 ? distanceBetweenPointers() : null;
  if (!pointers.size) map.classList.remove("dragging");
}

map.addEventListener("pointerup", releasePointer);
map.addEventListener("pointercancel", releasePointer);
map.addEventListener("click", hideAirport);
document.addEventListener("keydown", event => { if (event.key === "Escape") hideAirport(); });
window.addEventListener("resize", () => { if (state.airports.size) renderMap(); });

document.querySelector("#route-form").addEventListener("submit", event => {
  event.preventDefault();
  applyRoute();
  try { localStorage.setItem(ROUTE_STORAGE_KEY, state.route.join("-")); } catch (error) { console.warn("Could not save route", error); }
  routePanel.open = false;
});

try {
  routeInput.value = localStorage.getItem(ROUTE_STORAGE_KEY) || "";
} catch (error) {
  console.warn("Could not load route", error);
}

function updatePlanningControls() {
  currentLocationButton.setAttribute("aria-pressed", String(!state.locationOverride));
  groundspeedSetting.hidden = !state.aircraftPosition || (!state.locationOverride && state.detectedSpeedKnots !== null);
}

function applyPlanningLocation(interactive = true) {
  const id = planningLocationInput.value.trim().toUpperCase();
  const airport = id ? state.airports.get(id) : null;
  planningLocationInput.setCustomValidity(id && !airport ? "Enter an airport identifier shown on the map" : "");
  if (id && !airport) {
    if (interactive) planningLocationInput.reportValidity();
    return;
  }
  planningLocationInput.value = id;
  state.locationOverride = airport?.position || null;
  state.aircraftPosition = state.locationOverride || state.actualPosition;
  try {
    if (id) localStorage.setItem(PLANNING_LOCATION_STORAGE_KEY, id);
    else localStorage.removeItem(PLANNING_LOCATION_STORAGE_KEY);
  } catch (error) {
    console.warn("Could not save planning location", error);
  }
  updatePlanningControls();
  if (interactive) centerOnNextPosition = !state.aircraftPosition;
  if (state.airports.size) {
    if (interactive && state.aircraftPosition) centerMapOnPosition(state.aircraftPosition);
    else renderMap();
  }
}

function setAircraftPosition(latitude, longitude, speedKnots) {
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude) || Math.abs(latitude) > 90 || Math.abs(longitude) > 180) return;
  state.actualPosition = { latitude, longitude };
  if (!state.locationOverride) state.aircraftPosition = state.actualPosition;
  state.detectedSpeedKnots = Number.isFinite(speedKnots) && speedKnots > 0 ? speedKnots : null;
  updatePlanningControls();
  if (state.airports.size) {
    if (centerOnNextPosition && !state.locationOverride) {
      centerOnNextPosition = false;
      centerMapOnPosition(state.aircraftPosition);
    } else renderMap();
  }
}

async function updateStratuxPosition() {
  const response = await fetch("/getSituation", { cache: "no-store" });
  if (!response.ok) throw new Error(`Stratux situation returned ${response.status}`);
  const situation = await response.json();
  if (situation.GPSFixQuality > 0) setAircraftPosition(situation.GPSLatitude, situation.GPSLongitude, situation.GPSGroundSpeed);
}

function setBrowserPosition(position) {
  const speedKnots = Number.isFinite(position.coords.speed) ? position.coords.speed * 1.943844 : null;
  setAircraftPosition(position.coords.latitude, position.coords.longitude, speedKnots);
}

function startPositionUpdates() {
  if (isStratux()) {
    updateStratuxPosition().catch(error => console.warn("Stratux position unavailable", error));
    setInterval(() => updateStratuxPosition().catch(error => console.warn("Stratux position unavailable", error)), 2000);
  } else if (navigator.geolocation) {
    navigator.geolocation.watchPosition(setBrowserPosition, error => console.warn("Browser position unavailable", error), { enableHighAccuracy: true, maximumAge: 5000 });
  }
}

planningLocationInput.addEventListener("input", () => {
  planningLocationInput.setCustomValidity("");
  renderAirportOptions(planningLocationInput.value);
});
planningLocationInput.addEventListener("change", () => applyPlanningLocation());
currentLocationButton.addEventListener("click", () => {
  planningLocationInput.value = "";
  applyPlanningLocation();
  planningLocationInput.value = "K";
  renderAirportOptions("K");
  if (!state.actualPosition) {
    if (isStratux()) updateStratuxPosition().catch(error => console.warn("Stratux position unavailable", error));
    else navigator.geolocation?.getCurrentPosition(setBrowserPosition, error => console.warn("Browser position unavailable", error), { enableHighAccuracy: true, maximumAge: 5000 });
  }
});

groundspeedInput.addEventListener("change", () => {
  const speed = Number(groundspeedInput.value);
  state.manualSpeedKnots = groundspeedInput.checkValidity() && Number.isFinite(speed) && speed > 0 ? speed : null;
  try {
    if (state.manualSpeedKnots) localStorage.setItem(MANUAL_SPEED_STORAGE_KEY, String(state.manualSpeedKnots));
    else localStorage.removeItem(MANUAL_SPEED_STORAGE_KEY);
  } catch (error) {
    console.warn("Could not save manual groundspeed", error);
  }
  if (state.airports.size) renderMap();
});

try {
  const savedSpeed = Number(localStorage.getItem(MANUAL_SPEED_STORAGE_KEY));
  if (Number.isFinite(savedSpeed) && savedSpeed > 0 && savedSpeed <= 550) {
    state.manualSpeedKnots = savedSpeed;
    groundspeedInput.value = String(savedSpeed);
  }
} catch (error) {
  console.warn("Could not load manual groundspeed", error);
}

fuelRemainingInput.addEventListener("input", event => {
  fuelRemainingInput.value = insertDurationColon(fuelRemainingInput.value, event.inputType);
  state.fuelMinutes = fuelRemainingInput.value ? parseDuration(fuelRemainingInput.value) : null;
  fuelRemainingInput.setCustomValidity(fuelRemainingInput.value && state.fuelMinutes === null ? "Use hours:minutes, for example 3:30" : "");
  try {
    if (state.fuelMinutes !== null) localStorage.setItem(FUEL_REMAINING_STORAGE_KEY, fuelRemainingInput.value);
    else if (!fuelRemainingInput.value) localStorage.removeItem(FUEL_REMAINING_STORAGE_KEY);
  } catch (error) {
    console.warn("Could not save fuel remaining", error);
  }
  if (state.airports.size) renderMap();
});
fuelRemainingInput.addEventListener("change", () => fuelRemainingInput.reportValidity());

try {
  savedPlanningLocation = localStorage.getItem(PLANNING_LOCATION_STORAGE_KEY) || "";
  planningLocationInput.value = savedPlanningLocation || "K";
  fuelRemainingInput.value = localStorage.getItem(FUEL_REMAINING_STORAGE_KEY) || "";
  state.fuelMinutes = fuelRemainingInput.value ? parseDuration(fuelRemainingInput.value) : null;
} catch (error) {
  planningLocationInput.value = "K";
  console.warn("Could not load range planning", error);
}

function setSymbolScale(value, persist = false) {
  value = Math.min(Number(symbolSizeInput.max), Math.max(Number(symbolSizeInput.min), value));
  state.symbolScale = value;
  symbolSizeInput.value = String(value);
  symbolSizeLabel.value = `${Math.round(value * 100)}%`;
  if (persist) {
    try { localStorage.setItem(SYMBOL_SIZE_STORAGE_KEY, String(value)); } catch (error) { console.warn("Could not save symbol size", error); }
  }
  if (state.airports.size) renderMap();
}

symbolSizeInput.addEventListener("input", () => setSymbolScale(Number(symbolSizeInput.value), true));
document.querySelector("#settings-open").addEventListener("click", () => settingsDialog.showModal());
settingsDialog.addEventListener("click", event => {
  const bounds = settingsDialog.getBoundingClientRect();
  if (event.target === settingsDialog && (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom)) settingsDialog.close();
});
document.querySelector("#settings-clear").addEventListener("click", () => {
  planningLocationInput.value = "K";
  planningLocationInput.setCustomValidity("");
  groundspeedInput.value = "";
  fuelRemainingInput.value = "";
  fuelRemainingInput.setCustomValidity("");
  state.locationOverride = null;
  state.aircraftPosition = state.actualPosition;
  state.manualSpeedKnots = null;
  state.fuelMinutes = null;
  try {
    [PLANNING_LOCATION_STORAGE_KEY, MANUAL_SPEED_STORAGE_KEY, FUEL_REMAINING_STORAGE_KEY].forEach(key => localStorage.removeItem(key));
  } catch (error) {
    console.warn("Could not clear flight settings", error);
  }
  renderAirportOptions("K");
  updatePlanningControls();
  if (state.airports.size) renderMap();
});

try {
  const savedSymbolScale = Number(localStorage.getItem(SYMBOL_SIZE_STORAGE_KEY));
  if (Number.isFinite(savedSymbolScale) && savedSymbolScale > 0) setSymbolScale(savedSymbolScale);
} catch (error) {
  console.warn("Could not load symbol size", error);
}

if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js");
startPositionUpdates();

loadData().then(() => {
  applyRoute();
  if (savedPlanningLocation) applyPlanningLocation(false);
  else if (centerOnNextPosition && state.aircraftPosition) {
    centerOnNextPosition = false;
    centerMapOnPosition(state.aircraftPosition);
  } else updatePlanningControls();
}).catch(error => {
  document.querySelector("#data-status").textContent = `Fuel data unavailable: ${error.message}`;
});
